def get_compatible_vehicles_for_item(row_id: str, part_name: str = "") -> str:
    """
    دریافت دقیق لیست خودروهای سازگار (اشتراکات) بر اساس شماره ردیف اکسل (۱ تا ۶۱)
    مطابق کارت فنی مربوطه در کاتالوگ جامع شرکت کیالنت البرز نور
    """
    try:
        s_clean = to_en_str(str(row_id).strip()).split('_')[0]
        m = re.match(r'^(\d+)', s_clean)
        base_row = int(m.group(1)) if m else int(float(s_clean))
        if base_row in ROW_BASE_COMPATIBILITY_MAP:
            return ROW_BASE_COMPATIBILITY_MAP[base_row]
    except Exception:
        pass
    return "مطابق کاتالوگ رسمی شرکت کیالنت البرز نور"


