PERSIAN_DIGITS = str.maketrans("0123456789,", "۰۱۲۳۴۵۶۷۸۹،")
ENGLISH_DIGITS = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")


def to_fa_num(val, comma=False) -> str:
    if comma and isinstance(val, (int, float)):
        s = f"{int(val):,}"
    else:
        s = str(val)
    return s.translate(PERSIAN_DIGITS)


def to_en_str(s: str) -> str:
    return str(s).translate(ENGLISH_DIGITS)


def gregorian_to_jalali(gy: int, gm: int, gd: int):
    g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
    gy2 = gy + 1 if gm > 2 else gy
    days = (
        355666
        + (365 * gy)
        + ((gy2 + 3) // 4)
        - ((gy2 + 99) // 100)
        + ((gy2 + 399) // 400)
        + gd
        + g_d_m[gm - 1]
    )
    jy = -1595 + (33 * (days // 12053))
    days %= 12053
    jy += 4 * (days // 1461)
    days %= 1461
    if days > 365:
        jy += (days - 1) // 365
        days = (days - 1) % 365
    if days < 186:
        jm = 1 + (days // 31)
        jd = 1 + (days % 31)
    else:
        jm = 7 + ((days - 186) // 30)
        jd = 1 + ((days - 186) % 30)
    return f"{jy:04d}/{jm:02d}/{jd:02d}"


def get_today_jalali() -> str:
    now = datetime.datetime.now()
    return gregorian_to_jalali(now.year, now.month, now.day)


ONES = ["", "یک", "دو", "سه", "چهار", "پنج", "شش", "هفت", "هشت", "نه"]
TEENS = ["ده", "یازده", "دوازده", "سیزده", "چهارده", "پانزده", "شانزده", "هفده", "هجده", "نوزده"]
TENS = ["", "", "بیست", "سی", "چهل", "پنجاه", "شصت", "هفتاد", "هشتاد", "نود"]
HUNDREDS = ["", "یکصد", "دویست", "سیصد", "چهارصد", "پانصد", "ششصد", "هفتصد", "هشتصد", "نهصد"]
SCALE = ["", "هزار", "میلیون", "میلیارد", "تریلیون"]


def _three_digits_to_words(n: int) -> str:
    if n == 0:
        return ""
    parts = []
    h = n // 100
    rem = n % 100
    if h > 0:
        parts.append(HUNDREDS[h])
    if 10 <= rem <= 19:
        parts.append(TEENS[rem - 10])
    else:
        t = rem // 10
        o = rem % 10
        if t > 0:
            parts.append(TENS[t])
        if o > 0:
            parts.append(ONES[o])
    return " و ".join(parts)


def num_to_persian_words(n: int) -> str:
    n = int(n)
    if n == 0:
        return "صفر"
    groups = []
    scale_idx = 0
    while n > 0:
        grp = n % 1000
        if grp > 0:
            w = _three_digits_to_words(grp)
            if SCALE[scale_idx]:
                w += " " + SCALE[scale_idx]
            groups.append(w)
        n //= 1000
        scale_idx += 1
    return " و ".join(reversed(groups))


